INSERT INTO `user_recommendations` (`id`, `user_id`, `health_issues`, `lifestyle`, `severity`, `preferences`, `yoga`, `remedies`, `created_at`) VALUES
(26, 6, 'upper back pain', 'Mixed, Sedentary activity, 6h sleep', 'Moderate', NULL, '[{\"name\":\"Bhujangasana\",\"image_keyword\":\"bhujangasana.jpg\",\"benefits\":\"Strengthens back muscles and improves flexibility.\",\"steps\":[\"Lie on your stomach with your hands under your shoulders\",\"Inhale and press your palms into the ground, lifting your chest and head off the ground\",\"Hold for 5 breaths and release\"],\"duration\":\"5 mins\",\"contraindications\":\"Avoid if you have a neck or back injury.\",\"video\":\"https://youtu.be/luTSRGXPEMs\"},{\"name\":\"Balasana\",\"image_keyword\":\"balasana.jpg\",\"benefits\":\"Stretches and relaxes the back muscles.\",\"steps\":[\"Kneel on the ground with your knees wide apart\",\"Sit back onto your heels\",\"Stretch your arms out in front of you and lower your forehead to the ground\"],\"duration\":\"5 mins\",\"contraindications\":\"Avoid if you have a knee injury.\",\"video\":\"https://youtu.be/2MJGg-dUKh0\"},{\"name\":\"Marjariasana\",\"image_keyword\":\"marjariasana.jpg\",\"benefits\":\"Stretches and flexes the spine, relieving tension.\",\"steps\":[\"Start on your hands and knees\",\"Inhale and arch your back, lifting your tailbone and head towards the ceiling\",\"Exhale and round your back, tucking your chin towards your chest\"],\"duration\":\"5 mins\",\"contraindications\":\"Avoid if you have a neck or back injury.\",\"video\":\"https://youtu.be/Ov65nNSWrfw\"},{\"name\":\"Setu Bandha\",\"image_keyword\":\"setu_bandha.jpg\",\"benefits\":\"Strengthens the back muscles and improves posture.\",\"steps\":[\"Lie on your back with your knees bent and feet flat on the ground\",\"Inhale and lift your hips towards the ceiling\",\"Hold for 5 breaths and release\"],\"duration\":\"5 mins\",\"contraindications\":\"Avoid if you have a back injury.\",\"video\":\"https://youtu.be/g78vfuC4QBI\"}]', '{\"remedies\":[{\"name\":\"Tulsi Ginger Kadha\",\"image_keyword\":\"tulsi_ginger_kadha.jpg\",\"usage\":\"Drink 1 cup, 2 times a day.\",\"benefits\":\"Reduces inflammation and alleviates pain.\",\"type\":\"Herb\",\"ingredients\":[\"Tulsi leaves\",\"Ginger\",\"Honey\"],\"preparation_time\":\"10 mins\",\"video\":\"https://youtube.com/shorts/7WnEZyRFlK8?si=4874ls27t1rDryRa\"},{\"name\":\"Turmeric Milk\",\"image_keyword\":\"tumeric_milk.jpg\",\"usage\":\"Drink 1 cup, before bed.\",\"benefits\":\"Reduces inflammation and promotes relaxation.\",\"type\":\"Herb\",\"ingredients\":[\"Turmeric\",\"Milk\",\"Honey\"],\"preparation_time\":\"5 mins\",\"video\":\"https://youtube.com/shorts/Ih8ps6Ti_K0?si=GSblIS0725Ux6hxv\"},{\"name\":\"Ajwain Water\",\"image_keyword\":\"ajwain_water.jpg\",\"usage\":\"Drink 1 cup, 2 times a day.\",\"benefits\":\"Aids digestion and reduces pain.\",\"type\":\"Herb\",\"ingredients\":[\"Ajwain seeds\",\"Water\"],\"preparation_time\":\"5 mins\",\"video\":\"https://youtube.com/shorts/SRG69qwzPT4?si=OAMONK8azUGpXCWE\"},{\"name\":\"Ginger Lemon\",\"image_keyword\":\"ginger_lemon.jpg\",\"usage\":\"Drink 1 cup, 2 times a day.\",\"benefits\":\"Reduces inflammation and alleviates pain.\",\"type\":\"Herb\",\"ingredients\":[\"Ginger\",\"Lemon\",\"Honey\"],\"preparation_time\":\"5 mins\",\"video\":\"https://youtube.com/shorts/UJzkdo4spd0?si=ViOME2xJ9aI_I7UC\"}],\"dietTips\":[\"Avoid spicy and sour foods\",\"Include cooling and calming foods like cucumbers and yogurt\",\"Drink plenty of water throughout the day\"],\"lifestyleTips\":[\"Get at least 7-8 hours of sleep per night\",\"Practice stress-reducing techniques like meditation and deep breathing\",\"Take regular breaks to stretch and move throughout the day\"],\"summary\":\"As a 44-year-old female with a Pitta Prakriti, you are experiencing moderate upper back pain, which can be alleviated with the right combination of yoga, remedies, and lifestyle adjustments. By incorporating these recommendations into your daily routine, you can find relief from pain and improve your overall well-being.\",\"doshaAnalysis\":\"The imbalance in your Pitta dosha is likely contributing to the upper back pain, as Pitta types tend to experience inflammation and heat in the body. To restore balance, it\'s essential to focus on cooling and calming practices that will help reduce the Pitta imbalance and alleviate the pain.\"}', '2026-01-09 07:40:23'),
(27, 6, 'body pain', 'Mixed, Sedentary activity, 9h sleep', 'Moderate', NULL, '[{\"name\":\"Sukhasana\",\"image_keyword\":\"sukhasana.jpg\",\"benefits\":\"Relaxes the mind and body, reducing pain and inflammation.\",\"steps\":[\"Sit comfortably with your back straight\",\"Close your eyes and focus on your breath\",\"Stay for 5-10 minutes\"],\"duration\":\"5-10 mins\",\"contraindications\":\"Avoid if you have any severe back or knee injuries.\",\"video\":\"https://youtu.be/ri9B8IzLXIY\"},{\"name\":\"Marjariasana\",\"image_keyword\":\"marjariasana.jpg\",\"benefits\":\"Gently stretches and strengthens the spine, relieving back pain.\",\"steps\":[\"Start on your hands and knees\",\"Inhale and arch your back\",\"Exhale and round your back\"],\"duration\":\"5 mins\",\"contraindications\":\"Avoid if you have any severe neck or back injuries.\",\"video\":\"https://youtu.be/Ov65nNSWrfw\"},{\"name\":\"Pawanmuktasana\",\"image_keyword\":\"pawanmuktasana.jpg\",\"benefits\":\"Relaxes the muscles and improves digestion, reducing body pain.\",\"steps\":[\"Lie on your back and bring one knee towards your chest\",\"Hold for a few breaths and then release\",\"Repeat on the other side\"],\"duration\":\"5 mins\",\"contraindications\":\"Avoid if you have any severe abdominal or back injuries.\",\"video\":\"https://youtu.be/UArmfqhbWLk\"},{\"name\":\"Shavasana\",\"image_keyword\":\"shavasana.jpg\",\"benefits\":\"Deeply relaxes the mind and body, reducing pain and inflammation.\",\"steps\":[\"Lie on your back with your arms and legs relaxed\",\"Close your eyes and focus on your breath\",\"Stay for 5-10 minutes\"],\"duration\":\"5-10 mins\",\"contraindications\":\"Avoid if you have any severe back or neck injuries.\",\"video\":\"https://youtu.be/nF4WqMRbfdI\"}]', '{\"remedies\":[{\"name\":\"Turmeric Milk\",\"image_keyword\":\"tumeric_milk.jpg\",\"usage\":\"Drink 1 cup of warm turmeric milk before bed\",\"benefits\":\"Reduces inflammation and pain, promoting relaxation and sleep.\",\"type\":\"Herb\",\"ingredients\":\"1 cup milk, 1/2 teaspoon turmeric powder\",\"preparation_time\":\"5 mins\",\"video\":\"https://youtube.com/shorts/Ih8ps6Ti_K0?si=GSblIS0725Ux6hxv\"},{\"name\":\"Ginger Lemon\",\"image_keyword\":\"ginger_lemon.jpg\",\"usage\":\"Drink 1 cup of ginger lemon tea twice a day\",\"benefits\":\"Reduces pain and inflammation, improving digestion and immunity.\",\"type\":\"Herb\",\"ingredients\":\"1 cup water, 1/2 lemon, 1/2 inch ginger\",\"preparation_time\":\"5 mins\",\"video\":\"https://youtube.com/shorts/UJzkdo4spd0?si=ViOME2xJ9aI_I7UC\"},{\"name\":\"Ashwagandha\",\"image_keyword\":\"ashwagandha.jpg\",\"usage\":\"Take 1 teaspoon of ashwagandha powder with warm water twice a day\",\"benefits\":\"Reduces stress and anxiety, promoting relaxation and sleep.\",\"type\":\"Herb\",\"ingredients\":\"1 teaspoon ashwagandha powder\",\"preparation_time\":\"1 min\",\"video\":\"https://youtube.com/shorts/n7ih57stldQ?si=ueZT7z7oHotuv7nh\"},{\"name\":\"Tulsi Ginger Kadha\",\"image_keyword\":\"tulsi_ginger_kadha.jpg\",\"usage\":\"Drink 1 cup of tulsi ginger kadha twice a day\",\"benefits\":\"Reduces pain and inflammation, improving digestion and immunity.\",\"type\":\"Herb\",\"ingredients\":\"1 cup water, 1/2 cup tulsi leaves, 1/2 inch ginger\",\"preparation_time\":\"10 mins\",\"video\":\"https://youtube.com/shorts/7WnEZyRFlK8?si=4874ls27t1rDryRa\"}],\"dietTips\":[\"Eat a balanced diet with plenty of fruits, vegetables, and whole grains\",\"Include anti-inflammatory foods like turmeric, ginger, and omega-3 fatty acids\",\"Avoid spicy, sour, and salty foods that can exacerbate Pitta imbalance\"],\"lifestyleTips\":[\"Practice stress-reducing techniques like meditation and deep breathing\",\"Engage in gentle exercises like yoga and walking\",\"Get at least 7-8 hours of sleep each night to help regulate your doshas\"],\"summary\":\"As a 64-year-old male with a Pitta prakriti, you\'re more prone to experiencing body pain and inflammation, which can be managed through gentle yoga practices and Ayurvedic remedies. By incorporating the recommended yoga poses, ayurvedic remedies, and lifestyle adjustments, you can alleviate your body pain and improve your overall well-being.\",\"doshaAnalysis\":\"Your Pitta dosha is dominant, which can lead to increased heat and inflammation in the body, contributing to your body pain. To balance your dosha, it\'s essential to focus on cooling and calming practices, such as gentle yoga and herbal remedies.\"}', '2026-01-20 07:21:58'),
(28, 6, 'Back pain', 'Age: 33, Gender: Male', 'Mild', NULL, '[{\"name\":\"Bhujangasana\",\"image_keyword\":\"bhujangasana.jpg\",\"benefits\":\"Strengthens back muscles and improves flexibility\",\"steps\":[\"Lie on your stomach with your hands under your shoulders\",\"Inhale and press your palms into the ground, lifting your chest and head off the ground\",\"Keep your shoulders down and away from your ears, and engage your core muscles\"],\"duration\":\"3-5 mins\",\"contraindications\":\"Avoid if you have a herniated disk or severe back injury\",\"video\":\"https://youtu.be/luTSRGXPEMs\"},{\"name\":\"Balasana\",\"image_keyword\":\"balasana.jpg\",\"benefits\":\"Stretches and relaxes the back muscles\",\"steps\":[\"Kneel on the ground with your knees wide apart\",\"Sit back onto your heels and stretch your arms out in front of you\",\"Lower your forehead to the ground, relaxing your entire body\"],\"duration\":\"3-5 mins\",\"contraindications\":\"Avoid if you have a knee injury or severe back pain\",\"video\":\"https://youtu.be/2MJGg-dUKh0\"},{\"name\":\"Marjariasana\",\"image_keyword\":\"marjariasana.jpg\",\"benefits\":\"Stretches and strengthens the spine\",\"steps\":[\"Start on your hands and knees\",\"Arch your back, lifting your tailbone and head towards the ceiling\",\"Then, round your back, tucking your chin to your chest and your tailbone towards the ground\"],\"duration\":\"3-5 mins\",\"contraindications\":\"Avoid if you have a neck or back injury\",\"video\":\"https://youtu.be/Ov65nNSWrfw\"},{\"name\":\"Setu Bandha Sarvangasana\",\"image_keyword\":\"setu_bandha.jpg\",\"benefits\":\"Strengthens the back muscles and improves posture\",\"steps\":[\"Lie on your back with your knees bent and feet flat on the ground\",\"Lift your hips towards the ceiling, squeezing your glutes and lower back muscles\",\"Hold for a few breaths, then slowly lower back down\"],\"duration\":\"3-5 mins\",\"contraindications\":\"Avoid if you have a severe back injury or herniated disk\",\"video\":\"https://youtu.be/g78vfuC4QBI\"}]', '{\"remedies\":[{\"name\":\"Tulsi Ginger Kadha\",\"image_keyword\":\"tulsi_ginger_kadha.jpg\",\"usage\":\"Drink 1-2 cups per day\",\"benefits\":\"Reduces inflammation and pain\",\"type\":\"Herb\",\"ingredients\":[\"Tulsi leaves\",\"Ginger\",\"Honey\"],\"preparation_time\":\"10 mins\",\"video\":\"https://youtube.com/shorts/7WnEZyRFlK8?si=4874ls27t1rDryRa\"},{\"name\":\"Turmeric Milk\",\"image_keyword\":\"tumeric_milk.jpg\",\"usage\":\"Drink 1 cup per day before bed\",\"benefits\":\"Reduces inflammation and promotes relaxation\",\"type\":\"Herb\",\"ingredients\":[\"Turmeric powder\",\"Milk\",\"Honey\"],\"preparation_time\":\"5 mins\",\"video\":\"https://youtube.com/shorts/Ih8ps6Ti_K0?si=GSblIS0725Ux6hxv\"},{\"name\":\"Ajwain Water\",\"image_keyword\":\"ajwain_water.jpg\",\"usage\":\"Drink 1-2 cups per day\",\"benefits\":\"Aids digestion and reduces inflammation\",\"type\":\"Herb\",\"ingredients\":[\"Ajwain seeds\",\"Water\"],\"preparation_time\":\"10 mins\",\"video\":\"https://youtube.com/shorts/SRG69qwzPT4?si=OAMONK8azUGpXCWE\"},{\"name\":\"Ginger Lemon\",\"image_keyword\":\"ginger_lemon.jpg\",\"usage\":\"Drink 1-2 cups per day\",\"benefits\":\"Reduces inflammation and aids digestion\",\"type\":\"Herb\",\"ingredients\":[\"Ginger\",\"Lemon juice\",\"Honey\"],\"preparation_time\":\"10 mins\",\"video\":\"https://youtube.com/shorts/UJzkdo4spd0?si=ViOME2xJ9aI_I7UC\"}],\"dietTips\":[\"Avoid spicy and oily foods\",\"Include cooling and calming foods like cucumbers, melons, and gourds\",\"Drink plenty of water and herbal teas\"],\"lifestyleTips\":[\"Avoid strenuous activities and heavy lifting\",\"Take regular breaks to stretch and relax\",\"Practice stress-reducing techniques like meditation and deep breathing\"],\"summary\":\"As a 33-year-old male with a Pitta Prakriti, you\'re experiencing mild back pain, which can be managed through a combination of yoga, ayurvedic remedies, and lifestyle adjustments. By following the recommendations below, you can alleviate your back pain and maintain a healthy balance in your body and mind.\",\"doshaAnalysis\":\"The Pitta dosha is primarily responsible for the metabolism and energy production in the body, and an imbalance can lead to inflammation and pain. To address the back pain, we\'ll focus on pacifying the Pitta dosha through cooling and calming practices, while also strengthening the back muscles through specific yoga poses.\"}', '2026-01-20 09:30:45'),
(29, 6, 'high Blood Pressure', 'Age: 23, Gender: Male', 'Mild', NULL, '[{\"name\":\"Shavasana\",\"image_keyword\":\"shavasana.jpg\",\"benefits\":\"Relaxes the body and mind, reducing blood pressure.\",\"steps\":[\"Lie on your back with your arms and legs relaxed\",\"Close your eyes and focus on your breath\",\"Stay in this pose for 5-10 minutes\"],\"duration\":\"5-10 mins\",\"contraindications\":\"Avoid if you have any spinal injuries or discomfort\",\"video\":\"https://youtu.be/nF4WqMRbfdI\"},{\"name\":\"Anulom Vilom\",\"image_keyword\":\"anulom_vilom.jpg\",\"benefits\":\"Balances the breath and calms the nervous system.\",\"steps\":[\"Sit comfortably with your back straight\",\"Close your right nostril with your thumb and inhale through your left\",\"Close your left nostril with your ring finger and exhale through your right\"],\"duration\":\"5-10 mins\",\"contraindications\":\"Avoid if you have any respiratory issues\",\"video\":\"https://youtu.be/Nhw92icsQ1A\"},{\"name\":\"Uttanasana\",\"image_keyword\":\"uttanasana.jpg\",\"benefits\":\"Stretches the entire back side of the body, relieving tension.\",\"steps\":[\"Stand with your feet hip-width apart\",\"Bend forward, stretching your arms and torso\",\"Keep your knees slightly bent if necessary\"],\"duration\":\"3-5 mins\",\"contraindications\":\"Avoid if you have any back or hip injuries\",\"video\":\"https://youtu.be/RAZJ-rLYBF0\"},{\"name\":\"Bhujangasana\",\"image_keyword\":\"bhujangasana.jpg\",\"benefits\":\"Strengthens the back muscles and improves circulation.\",\"steps\":[\"Lie on your stomach with your hands under your shoulders\",\"Inhale and press your palms into the ground, lifting your chest and head\",\"Keep your shoulders down and away from your ears\"],\"duration\":\"3-5 mins\",\"contraindications\":\"Avoid if you have any neck or back injuries\",\"video\":\"https://youtu.be/luTSRGXPEMs\"}]', '{\"remedies\":[{\"name\":\"Tulsi Ginger Kadha\",\"image_keyword\":\"tulsi_ginger_kadha.jpg\",\"usage\":\"