(36, 6, 'upper leg pain', 'Age: 44, Gender: Male', 'Moderate', NULL, '[{\"name\":\"Uttanasana\",\"image_keyword\":\"uttanasana.jpg\",\"benefits\":\"Stretches and strengthens the legs, hips, and back\",\"steps\":[\"Stand with your feet hip-width apart\",\"Exhale and fold forward, reaching for your toes\",\"Keep your knees slightly bent if necessary\"],\"duration\":\"5 mins\",\"contraindications\":\"Avoid if you have a severe back injury or are pregnant\",\"video\":\"https://youtu.be/RAZJ-rLYBF0\"},{\"name\":\"Pawanmuktasana\",\"image_keyword\":\"pawanmuktasana.jpg\",\"benefits\":\"Releases tension in the legs and improves circulation\",\"steps\":[\"Lie on your back with your arms at your sides\",\"Lift your legs and bring them towards your chest\",\"Hold for a few breaths and release\"],\"duration\":\"5 mins\",\"contraindications\":\"Avoid if you have a severe back injury or are pregnant\",\"video\":\"https://youtu.be/UArmfqhbWLk\"},{\"name\":\"Tadasana\",\"image_keyword\":\"tadasana.jpg\",\"benefits\":\"Improves posture and balance\",\"steps\":[\"Stand with your feet hip-width apart\",\"Engage your core and lengthen your spine\",\"Feel grounded and centered\"],\"duration\":\"5 mins\",\"contraindications\":\"None\",\"video\":\"https://youtu.be/CTrRX7DcBSA\"},{\"name\":\"Sukhasana\",\"image_keyword\":\"sukhasana.jpg\",\"benefits\":\"Stretches the hips and legs, and promotes relaxation\",\"steps\":[\"Sit comfortably with your legs crossed\",\"Lengthen your spine and relax your shoulders\",\"Focus on your breath\"],\"duration\":\"5 mins\",\"contraindications\":\"None\",\"video\":\"https://youtu.be/ri9B8IzLXIY\"}]', '{\"remedies\":[{\"name\":\"Ashwagandha\",\"image_keyword\":\"ashwagandha.jpg\",\"usage\":\"Take 1-2 teaspoons of ashwagandha powder with warm water or milk\",\"benefits\":\"Reduces stress and inflammation, and promotes overall well-being\",\"type\":\"Herb\",\"ingredients\":\"Ashwagandha root powder\",\"preparation_time\":\"5 mins\",\"video\":\"https://youtub