(38, 6, 'Anxiety', 'Age: 31, Gender: Male', 'Mild', NULL, '[{\"name\":\"anulom_vilom\",\"image_keyword\":\"anulom_vilom.jpg\",\"benefits\":\"Balances the breath and calms the mind\",\"steps\":[\"Sit comfortably with your back straight\",\"Place your right hand in front of your face\",\"Close your right nostril with your thumb and inhale through your left nostril\",\"Close your left nostril with your ring finger and exhale through your right nostril\"],\"duration\":\"5-10 mins\",\"contraindications\":\"Avoid if you have any respiratory issues\",\"video\":\"https://youtu.be/Nhw92icsQ1A\"},{\"name\":\"bhastrika\",\"image_keyword\":\"bhastrika.jpg\",\"benefits\":\" Energizes the body and calms the mind\",\"steps\":[\"Sit comfortably with your back straight\",\"Inhale and exhale rapidly through your nose\",\"Keep your mouth closed and focus on your breath\"],\"duration\":\"3-5 mins\",\"contraindications\":\"Avoid if you have any heart conditions\",\"video\":\"https://youtu.be/yl34Xo7ReXE\"},{\"name\":\"shavasana\",\"image_keyword\":\"shavasana.jpg\",\"benefits\":\"Relaxes the body and mind\",\"steps\":[\"Lie down on your back with your arms and legs relaxed\",\"Close your eyes and focus on your breath\",\"Stay in this pose for as long as you feel comfortable\"],\"duration\":\"5-10 mins\",\"contraindications\":\"None\",\"video\":\"https://youtu.be/nF4WqMRbfdI\"},{\"name\":\"sukhasana\",\"image_keyword\":\"sukhasana.jpg\",\"benefits\":\"Calms the mind and promotes relaxation\",\"steps\":[\"Sit comfortably with your back straight\",\"Cross your legs and place your hands on your knees\",\"Close your eyes and focus on your breath\"],\"duration\":\"5-10 mins\",\"contraindications\":\"None\",\"video\":\"https://youtu.be/ri9B8IzLXIY\"}]', '{\"yoga\":[{\"name\":\"anulom_vilom\",\"image_keyword\":\"anulom_vilom.jpg\",\"benefits\":\"Balances the breath and calms the mind\",\"steps\":[\"Sit comfortably with your back straight\",\"Place your right hand in front of your face\",\"Close your right nostril with your thumb and inhale through your left nostril\",\"Close your left nostril with your ring finger and exhale through your right nostril\"],\"duration\":\"5-10 mins\",\"contraindications\":\"Avoid if you have any respiratory issues\",\"video\":\"https://youtu.be/Nhw92icsQ1A\"},{\"name\":\"bhastrika\",\"image_keyword\":\"bhastrika.jpg\",\"benefits\":\" Energizes the body and calms the mind\",\"steps\":[\"Sit comfortably with your back straight\",\"Inhale and exhale rapidly through your nose\",\"Keep your mouth closed and focus on your breath\"],\"duration\":\"3-5 mins\",\"contraindications\":\"Avoid if you have any heart conditions\",\"video\":\"https://youtu.be/yl34Xo7ReXE\"},{\"name\":\"shavasana\",\"image_keyword\":\"shavasana.jpg\",\"benefits\":\"Relaxes the body and mind\",\"steps\":[\"Lie down on your back with your arms and legs relaxed\",\"Close your eyes and focus on your breath\",\"Stay in this pose for as long as you feel comfortable\"],\"duration\":\"5-10 mins\",\"contraindications\":\"None\",\"video\":\"https://youtu.be/nF4WqMRbfdI\"},{\"name\":\"sukhasana\",\"image_keyword\":\"sukhasana.jpg\",\"benefits\":\"Calms the mind and promotes relaxation\",\"steps\":[\"Sit comfortably with your back straight\",\"Cross your legs and place your hands on your knees\",\"Close your eyes and focus on your breath\"],\"duration\":\"5-10 mins\",\"contraindications\":\"None\",\"video\":\"https://youtu.be/ri9B8IzLXIY\"}],\"ayurveda\":[{\"name\":\"Ashwagandha\",\"image_keyword\":\"ashwagandha.jpg\",\"usage\":\"Consume 1 teaspoon of ashwagandha powder with warm milk before bed\",\"benefits\":\"Reduces anxiety and stress\",\"type\":\"Herb\",\"ingredients\":\"Ashwagandha powder, warm milk\",\"preparation_time\":\"2 mins\",\"video\":\"https://youtube.com/shorts/n7ih57stldQ?si=ueZT7z7oHotuv7nh\"},{\"name\":\"Tulsi Ginger Kadha\",\"image_keyword\":\"tulsi_ginger_kadha.jpg\",\"usage\":\"Drink 1 cup of tulsi ginger kadha twice a day\",\"benefits\":\"Boosts immunity and reduces anxiety\",\"type\":\"Herb\",\"ingredients\":\"Tulsi leaves, ginger, honey, lemon\",\"preparation_time\":\"10 mins\",\"video\":\"https://youtube.com/shorts/7WnEZyRFlK8?si=4874ls27t1rDryRa\"},{\"name\":\"Brahmi Tea\",\"image_keyword\":\"brahmi_tea.jpg\",\"usage\":\"Drink 1 cup of brahmi tea twice a day\",\"benefits\":\"Improves memory and reduces anxiety\",\"type\":\"Herb\",\"ingredients\":\"Brahmi leaves, hot water, honey\",\"preparation_time\":\"5 mins\",\"video\":\"https://youtube.com/shorts/TPvJAbJg668?si=Ub-vOb42qBl1wMUw\"},{\"name\":\"Ginger Lemon\",\"image_keyword\":\"ginger_lemon.jpg\",\"usage\":\"Drink 1 cup of ginger lemon tea twice a day\",\"benefits\":\"Aids digestion and reduces anxiety\",\"type\":\"Herb\",\"ingredients\":\"Ginger, lemon, honey, hot water\",\"preparation_time\":\"5 mins\",\"video\":\"https://youtube.com/shorts/UJzkdo4spd0?si=ViOME2xJ9aI_I7UC\"}],\"diet_tips\":[\"Eat a balanced diet with plenty of fruits and vegetables\",\"Include omega-3 rich foods like salmon and walnuts in your diet\",\"Avoid sugary and processed foods\"],\"lifestyle_tips\":[\"Practice yoga and meditation regularly\",\"Get at least 7-8 hours of sleep each night\",\"Engage in physical activities like walking or jogging for at least 30 minutes a day\"],\"remedies\":[{\"name\":\"Ashwagandha\",\"image_keyword\":\"ashwagandha.jpg\",\"usage\":\"Consume 1 teaspoon of ashwagandha powder with warm milk before bed\",\"benefits\":\"Reduces anxiety and stress\",\"type\":\"Herb\",\"ingredients\":\"Ashwagandha powder, warm milk\",\"preparation_time\":\"2 mins\",\"video\":\"https://youtube.com/shorts/n7ih57stldQ?si=ueZT7z7oHotuv7nh\"},{\"name\":\"Tulsi Ginger Kadha\",\"image_keyword\":\"tulsi_ginger_kadha.jpg\",\"usage\":\"Drink 1 cup of tulsi ginger kadha twice a day\",\"benefits\":\"Boosts immunity and reduces anxiety\",\"type\":\"Herb\",\"ingredients\":\"Tulsi leaves, ginger, honey, lemon\",\"preparation_time\":\"10 mins\",\"video\":\"https://youtube.com/shorts/7WnEZyRFlK8?si=4874ls27t1rDryRa\"},{\"name\":\"Brahmi Tea\",\"image_keyword\":\"brahmi_tea.jpg\",\"usage\":\"Drink 1 cup of brahmi tea twice a day\",\"benefits\":\"Improves memory and reduces anxiety\",\"type\":\"Herb\",\"ingredients\":\"Brahmi leaves, hot water, honey\",\"preparation_time\":\"5 mins\",\"video\":\"https://youtube.com/shorts/TPvJAbJg668?si=Ub-vOb42qBl1wMUw\"},{\"name\":\"Ginger Lemon\",\"image_keyword\":\"ginger_lemon.jpg\",\"usage\":\"Drink 1 cup of ginger lemon tea twice a day\",\"benefits\":\"Aids digestion and reduces anxiety\",\"type\":\"Herb\",\"ingredients\":\"Ginger, lemon, honey, hot water\",\"preparation_time\":\"5 mins\",\"video\":\"https://youtube.com/shorts/UJzkdo4spd0?si=ViOME2xJ9aI_I7UC\"}],\"summary\":\"As a 31-year-old male with a Kapha prakriti, you are prone to anxiety and nervousness, but with the right yoga and Ayurvedic practices, you can find balance and calm. By incorporating simple yet effective remedies and lifestyle changes, you can alleviate your mild anxiety symptoms and improve your overall well-being.\",\"doshaAnalysis\":\"Your Kapha dosha imbalance is contributing to your anxiety, as Kapha types are more prone to emotional turmoil and attachment. To balance your dosha, it\'s essential to focus on practices that promote clarity, energy, and mental stability.\"}', '2026-02-18 12:43:15'),
(39, 6, 'Body Pain', 'Age: 44, Gender: Female', 'Moderate', NULL, '[{\"name\":\"Bhujangasana\",\"image_keyword\":\"bhujangasana.jpg\",\"benefits\":\"Stretches and strengthens the back muscles, relieving pain and tension.\",\"steps\":[\"Lie on your stomach with your hands under your shoulders.\",\"Inhale and press your palms into the ground, lifting your chest and head off the mat.\",\"Hold for 3-5 breaths and slowly lower back down.\"],\"duration\":\"5 mins\",\"contraindications\":\"Avoid if you have a recent back injury or are pregnant.\",\"video\":\"https://youtu.be/luTSRGXPEMs\"},{\"name\":\"Marjariasana\",\"image_keyword\":\"marjariasana.jpg\",\"benefits\":\"Gently stretches the spine, neck, and torso, relieving tension and pain.\",\"steps\":[\"Start on your hands and knees.\",\"Inhale and arch your back, lifting your tailbone and head towards the ceiling.\",\"Exhale and round your back, tucking your chin towards your chest and your tailbone towards the ground.\"],\"duration\":\"5 mins\",\"contraindications\":\"Avoid if you have a recent neck or back injury.\",\"video\":\"https://youtu.be/Ov65nNSWrfw\"},{\"name\":\"Sukhasana\",\"image_keyword\":\"sukhasana.jpg\",\"benefits\":\"A calming and soothing pose that helps to reduce stress and alleviate body pain.\",\"steps\":[\"Sit comfortably with your legs crossed.\",\"Lengthen your spine and relax your shoulders.\",\"Close your eyes and focus on your breath.\"],\"duration\":\"5-10 mins\",\"contraindications\":\"None.\",\"video\":\"https://youtu.be/ri9B8IzLXIY\"},{\"name\":\"Tadasana\",\"image_keyword\":\"tadasana.jpg\",\"benefits\":\"Helps to establish good posture, reducing strain on the back and alleviating pain.\",\"steps\":[\"Stand with your feet hip-width apart.\",\"Engage your core and lengthen your spine.\",\"Relax your shoulders and arms by your sides.\"],\"duration\":\"5 mins\",\"contraindications\":\"None.\",\"video\":\"https://youtu.be/CTrRX7DcBSA\"}]', '{\"yoga\":[{\"name\":\"Bhujangasana\",\"image_keyword\":\"bhujangasana.jpg\",\"benefits\":\"Stretches and strengthens the back muscles, relieving pain and tension.\",\"steps\":[\"Lie on your stomach with your hands under your shoulders.\",\"Inhale and press your palms into the ground, lifting your chest and head off the mat.\",\"Hold for 3-5 breaths and slowly lower back down.\"],\"duration\":\"5 mins\",\"contraindications\":\"Avoid if you have a recent back injury or are pregnant.\",\"video\":\"https://youtu.be/luTSRGXPEMs\"},{\"name\":\"Marjariasana\",\"image_keyword\":\"marjariasana.jpg\",\"benefits\":\"Gently stretches the spine, neck, and torso, relieving tension and pain.\",\"steps\":[\"Start on your hands and knees.\",\"Inhale and arch your back, lifting your tailbone and head towards the ceiling.\",\"Exhale and round your back, tucking your chin towards your chest and your tailbone towards the ground.\"],\"duration\":\"5 mins\",\"contraindications\":\"Avoid if you have a recent neck or back injury.\",\"video\":\"https://youtu.be/Ov65nNSWrfw\"},{\"name\":\"Sukhasana\",\"image_keyword\":\"sukhasana.jpg\",\"benefits\":\"A calming and soothing pose that helps to reduce stress and alleviate body pain.\",\"steps\":[\"Sit comfortably with your legs crossed.\",\"Lengthen your spine and relax your shoulders.\",\"Close your eyes and focus on your breath.\"],\"duration\":\"5-10 mins\",\"contraindications\":\"None.\",\"video\":\"https://youtu.be/ri9B8IzLXIY\"},{\"name\":\"Tadasana\",\"image_keyword\":\"tadasana.jpg\",\"benefits\":\"Helps to establish good posture, reducing strain on the back and alleviating pain.\",\"steps\":[\"Stand with your feet hip-width apart.\",\"Engage your core and lengthen your spine.\",\"Relax your shoulders and arms by your sides.\"],\"duration\":\"5 mins\",\"contraindications\":\"None.\",\"video\":\"https://youtu.be/CTrRX7DcBSA\"}],\"ayurveda\":[{\"name\":\"Ginger Lemon\",\"image_keyword\":\"ginger_lemon.jpg\",\"usage\":\"Drink as a warm tea, 2-3 times a day.\",\"benefits\":\"Helps to reduce