(45, 6, 'stomach pain ', 'Age: 33, Gender: Male', 'Moderate', NULL, '[{\"name\":\"Marjariasana\",\"image_keyword\":\"marjariasana.jpg\",\"benefits\":\"Stretches and relaxes the spine, relieving tension and discomfort in the abdominal area.\",\"steps\":[\"Start on your hands and knees\",\"Inhale and arch your back, lifting your tailbone and head towards the ceiling\",\"Exhale and round your back, tucking your chin towards your chest and your tailbone towards the floor\"],\"duration\":\"5 mins\",\"contraindications\":\"Avoid if you have any neck or back injuries\",\"video\":\"https://youtu.be/Ov65nNSWrfw\"},{\"name\":\"Pawanmuktasana\",\"image_keyword\":\"pawanmuktasana.jpg\",\"benefits\":\"Massages the abdominal organs, relieving gas and discomfort.\",\"steps\":[\"Lie on your back and bring your knees towards your chest\",\"Hold your knees with your hands and rock from side to side\",\"Release and repeat several times\"],\"duration\":\"3 mins\",\"contraindications\":\"Avoid if you have any abdominal surgery or severe back pain\",\"video\":\"https://youtu.be/UArmfqhbWLk\"},{\"name\":\"Bhujangasana\",\"image_keyword\":\"bhujangasana.jpg\",\"benefits\":\"Strengthens the back muscles and opens the chest, improving posture and reducing discomfort.\",\"steps\":[\"Lie on your stomach with your hands under your shoulders\",\"Inhale and press your palms into the ground, lifting your chest and head off the mat\",\"Hold for a few breaths and then release\"],\"duration\":\"3 mins\",\"contraindications\":\"Avoid if you have any neck or back injuries\",\"video\":\"https://youtu.be/luTSRGXPEMs\"},{\"name\":\"Sukhasana\",\"image_keyword\":\"sukhasana.jpg\",\"benefits\":\"Promotes relaxation and reduces stress, which can contribute to digestive issues.\",\"steps\":[\"Sit comfortably with your back straight\",\"Close your eyes and focus on your breath\",\"Stay for several minutes, feeling calm and relaxed\"],\"duration\":\"5 mins\",\"contraindications\":\"None\",\"video\":\"https://youtu.be/ri9B8IzLXIY\"}]', '{\"yoga\":[{\"name\":\"Marjariasana\",\"image_keyword\":\"marjariasana.jpg\",\"benefits\":\"Stretches and relaxes the spine, relieving tension and discomfort in the abdominal area.\",\"steps\":[\"Start on your hands and knees\",\"Inhale and arch your back, lifting your tailbone and head towards the ceiling\",\"Exhale and round your back, tucking your chin towards your chest and your tailbone towards the floor\"],\"duration\":\"5 mins\",\"contraindications\":\"Avoid if you have any neck or back injuries\",\"video\":\"https://youtu.be/Ov65nNSWrfw\"},{\"name\":\"Pawanmuktasana\",\"image_keyword\":\"pawanmuktasana.jpg\",\"benefits\":\"Massages the abdominal organs, relieving gas and discomfort.\",\"steps\":[\"Lie on your back and bring your knees towards your chest\",\"Hold your knees with your hands and rock from side to side\",\"Release and repeat several times\"],\"duration\":\"3 mins\",\"contraindications\":\"Avoid if you have any abdominal surgery or severe back pain\",\"video\":\"https://youtu.be/UArmfqhbWLk\"},{\"name\":\"Bhujangasana\",\"image_keyword\":\"bhujangasana.jpg\",\"benefits\":\"Strengthens the back muscles and opens the chest, improving posture and reducing discomfort.\",\"steps\":[\"Lie on your stomach with your hands under your shoulders\",\"Inhale and press your palms into the ground, lifting your chest and head off the mat\",\"Hold for a few breaths and then release\"],\"duration\":\"3 mins\",\"contraindications\":\"Avoid if you have any neck or back injuries\",\"video\":\"https://youtu.be/luTSRGXPEMs\"},{\"name\":\"Sukhasana\",\"image_keyword\":\"sukhasana.jpg\",\"benefits\":\"Promotes relaxation and reduces stress, which can contribute to digestive issues.\",\"steps\":[\"Sit comfortably with your back straight\",\"Close your eyes and focus on your breath\",\"Stay for several minutes, feeling calm and relaxed\"],\"duration\":\"5 mins\",\"contraindications\":\"None\",\"video\":\"https://youtu.be/ri9B8IzLXIY\"}],\"ayurveda