(49, 6, 'fever', 'Age: 12, Gender: Female', 'Moderate', NULL, '[{\"name\":\"Bhujangasana\",\"image_keyword\":\"bhujangasana.jpg\",\"video\":\"https://youtu.be/luTSRGXPEMs\",\"benefits\":\"Strengthens spine and posture\",\"steps\":[\"Lie flat on your stomach with legs together and tops of feet on the floor.\",\"Place hands under shoulders, elbows close to the body.\",\"Inhale and slowly lift your chest off the floor while keeping the navel down.\",\"Keep shoulders relaxed and gaze slightly upward.\",\"Hold for 15-30 seconds, then exhale and lower slowly.\"],\"duration\":\"5 mins\",\"reps_sets\":\"3-5 rounds\",\"contraindications\":\"severe_back_injury\"},{\"name\":\"Balasana\",\"image_keyword\":\"balasana.jpg\",\"video\":\"https://youtu.be/2MJGg-dUKh0\",\"benefits\":\"Relieves back tension and stress\",\"steps\":[\"Kneel on the floor with big toes touching and sit on your heels.\",\"Separate your knees about hip-width apart.\",\"Exhale and lay your torso down between your thighs.\",\"Rest your forehead on the mat and stretch your arms forward or alongside the body.\",\"Breathe deeply and hold for 1-3 minutes.\"],\"duration\":\"3 mins\",\"reps_sets\":\"3-5 rounds\",\"contraindications\":\"none\"},{\"name\":\"Marjariasana\",\"image_keyword\":\"marjariasana.jpg\",\"video\":\"https://youtu.be/Ov65nNSWrfw\",\"benefits\":\"Improves spinal flexibility\",\"steps\":[\"Start on your hands and knees in a tabletop position.\",\"Inhale, drop your belly, and look up toward the ceiling (Cow Pose).\",\"Exhale, round your spine, and tuck your chin toward your chest (Cat Pose).\",\"Flow between these two movements with your breath.\",\"Repeat for 10-15 rounds to improve spinal flexibility.\"],\"duration\":\"5 mins\",\"reps_sets\":\"3-5 rounds\",\"contraindications\":\"pregnancy\"},{\"name\":\"Sukhasana\",\"image_keyword\":\"sukhasana.jpg\",\"video\":\"https://youtu.be/ri9B8IzLXIY\",\"benefits\":\"Calms mind and posture\",\"steps\":[\"Sit with legs stretched out in front.\",\"Fold your legs and tuck your feet under opposite thighs.\",\"Keep your spine straight, shoulders relaxed, and hands on knees.\",\"Close your eyes and focus on deep, steady breathing.\",\"Maintain this pose for 5-10 minutes during meditation.\"],\"duration\":\"10 mins\",\"reps_sets\":\"3-5 rounds\",\"contraindications\":\"none\"},{\"name\":\"Anulom_Vilom\",\"image_keyword\":\"anulom_vilom.jpg\",\"video\":\"https://youtu.be/Nhw92icsQ1A\",\"benefits\":\"Improves breathing\",\"steps\":[\"Sit in a comfortable cross-legged position with spine straight.\",\"Close the right nostril with the thumb and inhale deeply through the left.\",\"Close the left nostril with the ring finger and exhale through the right.\",\"Inhale through the right, then close it and exhale through the left.\",\"Continue this cycle for 5-10 minutes.\"],\"duration\":\"10 mins\",\"reps_sets\":\"5-10 mins\",\"contraindications\":\"none\"}]', '{\"yoga\":[{\"name\":\"Bhujangasana\",\"image_keyword\":\"bhujangasana.jpg\",\"video\":\"https://youtu.be/luTSRGXPEMs\",\"benefits\":\"Strengthens spine and posture\",\"steps\":[\"Lie flat on your stomach with legs together and tops of feet on the floor.\",\"Place hands under shoulders, elbows close to the body.\",\"Inhale and slowly lift your chest off the floor while keeping the navel down.\",\"Keep shoulders relaxed and gaze slightly upward.\",\"Hold for 15-30 seconds, then exhale and lower slowly.\"],\"duration\":\"5 mins\",\"reps_sets\":\"3-5 rounds\",\"contraindications\":\"severe_back_injury\"},{\"name\":\"Balasana\",\"image_keyword\":\"balasana.jpg\",\"video\":\"https://youtu.be/2MJGg-dUKh0\",\"benefits\":\"Relieves back tension and stress\",\"steps\":[\"Kneel on the floor with big toes touching and sit on your heels.\",\"Separate your knees about hip-width apart.\",\"Exhale and lay your torso down between your thighs.\",\"Rest your forehead on the mat and stretch your arms forward or alongside the body.\",\"Breathe deeply and hold for 1-3 minutes.\"],\"duration\":\"3